if (hdrs) {
  hdrs = MimeHeaders_copy(hdrs);
  if (!hdrs) return 0;
}

object = (MimeObject*)PR_MALLOC(size);
if (!object) {
  PR_Free(hdrs);
  return 0;
}

// Ensure all plain data is zeroed, regardless of existing constructors.
memset(object, 0, size);
// Ensure constructors are called for all C++ members.
clazz->cpp_construct(object);
object->clazz = clazz;
object->headers = hdrs;
object->dontShowAsAttachment = false;

if (override_content_type && *override_content_type)
  object->content_type = strdup(override_content_type);

status = clazz->initialize(object);
